360	                    <img src={pixQr(pixParcialVal)} alt="QR Code PIX parcial" className="w-[200px] h-[200px] rounded-xl border border-blue-200" />
361	                    <p className="text-xs text-blue-700 text-center">Cliente escaneia para pagar {fmt(pixParcialVal)}</p>
362	                  </div>
363	                )}
