  // bg-X-50 / bg-X-100 (light surfaces only, not solid button 500/600/700 backgrounds)
  content = content.replace(
    new RegExp(`\\bbg-(${colors.join('|')})-(50|100)\\b(?!\\s+dark:)`, 'g'),
    (m, color, shade) => `${m} dark:bg-${darkFor[shade](color)}`
  );

  // border-X-100/200/300
  content = content.replace(
    new RegExp(`\\bborder-(${colors.join('|')})-(100|200|300)\\b(?!\\s+dark:)`, 'g'),
    (m, color, shade) => `${m} dark:border-${darkFor[shade](color)}`
  );

  // text-X-500..900
  content = content.replace(
    new RegExp(`\\btext-(${colors.join('|')})-(500|600|700|800|900)\\b(?!\\s+dark:)`, 'g'),
    (m, color, shade) => `${m} dark:text-${darkFor[shade](color)}`
  );

  fs.writeFileSync(file, content, 'utf8');
  console.log('done', file);
}

