import React, { useState, useEffect } from 'react';
import { getPlataformaConfig, updatePlataformaConfig, uploadImagemPlataforma } from '../../services/adminService';
import Icon from '../../components/AppIcon';
import ImageUpload from '../../components/ui/ImageUpload';
import AdminHeader from '../../components/admin/AdminHeader';

const ICONES = [
  'Utensils', 'UtensilsCrossed', 'ChefHat', 'Pizza', 'Sandwich', 'Soup', 'Coffee',
  'ShoppingBag', 'Store', 'Truck', 'Bike', 'Package', 'Star', 'Heart', 'Flame', 'Tag',
];

const ColorField = ({ label, value, onChange, allowTransparent = false }) => {
  const isTransparent = value === 'transparent';
  return (
    <div>
      <div className="flex items-center justify-between mb-1">
        <label className="block text-sm font-medium text-gray-700 dark:text-zinc-300">{label}</label>
        {allowTransparent && (
          <label className="flex items-center gap-1.5 text-xs text-gray-500 dark:text-zinc-400 cursor-pointer select-none">
            <input
              type="checkbox"
              checked={isTransparent}
              onChange={(e) => onChange(e.target.checked ? 'transparent' : '#FFFFFF')}
              className="rounded border-gray-300 dark:border-zinc-700 text-orange-500 focus:ring-orange-400"
            />
            Transparente
          </label>
        )}
      </div>
      {isTransparent ? (
        <div className="flex items-center gap-2 border border-dashed border-gray-300 dark:border-zinc-700 rounded-lg px-3 py-2 text-xs text-gray-400 dark:text-zinc-500"
          style={{ backgroundImage: 'repeating-conic-gradient(#e5e7eb 0% 25%, transparent 0% 50%)', backgroundSize: '10px 10px' }}>
          <Icon name="Eye" size={13} /> Fundo transparente — deixa o que estiver atrás aparecer
        </div>
      ) : (
        <div className="flex items-center gap-3">
          <input type="color" value={value} onChange={(e) => onChange(e.target.value)}
            className="w-12 h-10 rounded-lg border border-gray-300 dark:border-zinc-700 cursor-pointer p-0.5 bg-white dark:bg-zinc-800" />
          <input type="text" value={value} onChange={(e) => onChange(e.target.value)}
            className="flex-1 border border-gray-300 dark:border-zinc-700 bg-white dark:bg-zinc-800 text-gray-900 dark:text-zinc-100 rounded-lg px-3 py-2 text-sm font-mono focus:outline-none focus:ring-2 focus:ring-orange-400" />
          <div className="w-10 h-10 rounded-lg border border-gray-300 dark:border-zinc-700 flex-shrink-0" style={{ background: value }} />
        </div>
      )}
    </div>
  );
};

const OptionalBgField = ({ label, value, onChange }) => {
  const enabled = !!value;
  return (
    <div>
      <label className="flex items-center gap-1.5 text-xs text-gray-500 dark:text-zinc-400 cursor-pointer select-none mb-1">
        <input
          type="checkbox"
          checked={enabled}
          onChange={(e) => onChange(e.target.checked ? '#FFFFFF' : '')}
          className="rounded border-gray-300 dark:border-zinc-700 text-orange-500 focus:ring-orange-400"
        />
        {label}
      </label>
      {enabled && (
        <div className="flex items-center gap-3">
          <input type="color" value={value} onChange={(e) => onChange(e.target.value)}
            className="w-12 h-10 rounded-lg border border-gray-300 dark:border-zinc-700 cursor-pointer p-0.5 bg-white dark:bg-zinc-800" />
          <input type="text" value={value} onChange={(e) => onChange(e.target.value)}
            className="flex-1 border border-gray-300 dark:border-zinc-700 bg-white dark:bg-zinc-800 text-gray-900 dark:text-zinc-100 rounded-lg px-3 py-2 text-sm font-mono focus:outline-none focus:ring-2 focus:ring-orange-400" />
          <div className="w-10 h-10 rounded-lg border border-gray-300 dark:border-zinc-700 flex-shrink-0" style={{ background: value }} />
        </div>
      )}
    </div>

